parameters.jsCode:
const meta = $('Extract Email Metadata').item.json;

// Only what the sender typed this time. Without this, a reply supplying one
// missing detail has everything else read out of the quoted message below it --
// including a date of birth taken from "On Wed, Sep 16, 2026 at 1:28 PM".
function ownTextOf(body) {
  const t = String(body || '');
  const markers = [
    /-{2,}\s*Original Message/i,
    /\bOn\s+\w.{0,160}?\bwrote:/i,
    /^\s*>/m,
    /_{10,}/,
    /\bSent from (?:Proton Mail|my iPhone|my iPad|my Android|Yahoo Mail|Outlook)/i,
    /\bFrom:\s*.{0,120}\bSent:/i
  ];
  let cut = t.length;
  for (const m of markers) {
    const hit = t.match(m);
    if (hit && hit.index !== undefined && hit.index >= 0 && hit.index < cut) cut = hit.index;
  }
  return t.slice(0, cut);
}

const ownText = ownTextOf(meta.bodyText);
const bodyLower = ownText.toLowerCase();
const subjectLower = (meta.subject || '').toLowerCase();

// A concrete policy noun means they are asking about a RULE, not asking what
// we can do. "What are your fees" is a policy question; a bare "help" is not,
// and sending that to the policy assistant produces "not covered in our
// documents" and a pointless escalation instead of the list of what we offer.
const CONCRETE_POLICY = /\b(fee|fees|charge|charges|limit|limits|interest|rate|rates|overdraft|credit card|policy|policies|terms|wire|atm|loan|deposit|joint|closure|dispute|statement)\b/;

function detect(text) {
  const wantsOpen = /\b(open(ing)? an? account|new account|create an? account|set ?up an? account|start an? account|sign(ing)? ?up|register(ing|ration)?|become a (customer|member)|i (want|need|would like) an? account)\b/.test(text) && !/\bjoint\b/.test(text);
  const wantsHelp = /\b(help|what can (you|i) do|what do you do|how (do|does) (this|it) work|how to use|instructions|options|menu|commands|guide|get(ting)? started|what services)\b/.test(text) && !CONCRETE_POLICY.test(text);
  const wantsPolicy = !wantsHelp && /\b(policy|policies|fee|fees|limit|limits|overdraft|credit card|interest rate|rule|rules|terms|hours|branch|support|help)\b/.test(text);
  return { wantsOpen, wantsPolicy, wantsHelp };
}

let result = detect(bodyLower);
if (!result.wantsOpen && !result.wantsPolicy && !result.wantsHelp) {
  result = detect(subjectLower);
}

let fullName = null;
const fromMatch = String(meta.rawFrom || '').match(/^"?([^"<]+?)"?\s*<[^>]+>$/);
if (fromMatch && fromMatch[1].trim()) fullName = fromMatch[1].trim();
if (!fullName) {
  const nameMatch = ownText.match(/my name is\s+([A-Za-z][A-Za-z\s.'-]{1,60})/i);
  if (nameMatch) fullName = nameMatch[1].trim();
}
if (!fullName) fullName = meta.fromEmail.split('@')[0];

let accountType = 'checking';
if (/\bsavings?\b/.test(bodyLower + ' ' + subjectLower)) accountType = 'savings';

// ---- date of birth -------------------------------------------------------
// Accepts 2010-05-14, 14/05/2010, 14 May 2010 and May 14, 2010. Day-first is the
// default for the ambiguous numeric form, which is the convention in Pakistan;
// it is only swapped when day-first is impossible.
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

function pad(n) { return String(n).padStart(2, '0'); }

function buildDate(y, m, d) {
  if (!y || !m || !d || m < 1 || m > 12 || d < 1 || d > 31) return null;
  const iso = y + '-' + pad(m) + '-' + pad(d);
  const parsed = new Date(iso + 'T00:00:00Z');
  if (isNaN(parsed.getTime())) return null;
  // Reject roll-over dates such as 2010-02-31.
  if (parsed.getUTCFullYear() !== y || parsed.getUTCMonth() + 1 !== m || parsed.getUTCDate() !== d) return null;
  return iso;
}

function parseDob(text) {
  const t = String(text || '');
  let m;

  m = t.match(/\b((?:19|20)\d{2})-(\d{1,2})-(\d{1,2})\b/);
  if (m) { const d = buildDate(+m[1], +m[2], +m[3]); if (d) return d; }

  m = t.match(/\b(\d{1,2})(?:st|nd|rd|th)?[\s.,-]+([A-Za-z]{3,9})[\s.,-]+((?:19|20)\d{2})\b/);
  if (m) {
    const mo = MONTHS[m[2].slice(0, 3).toLowerCase()];
    if (mo) { const d = buildDate(+m[3], mo, +m[1]); if (d) return d; }
  }

  m = t.match(/\b([A-Za-z]{3,9})[\s.,-]+(\d{1,2})(?:st|nd|rd|th)?[\s.,-]+((?:19|20)\d{2})\b/);
  if (m) {
    const mo = MONTHS[m[1].slice(0, 3).toLowerCase()];
    if (mo) { const d = buildDate(+m[3], mo, +m[2]); if (d) return d; }
  }

  m = t.match(/\b(\d{1,2})[\/.-](\d{1,2})[\/.-]((?:19|20)\d{2})\b/);
  if (m) {
    let day = +m[1], mon = +m[2];
    if (day <= 12 && mon > 12) { const tmp = day; day = mon; mon = tmp; }
    const d = buildDate(+m[3], mon, day);
    if (d) return d;
  }

  return null;
}

const dobSource = ownText + '\n' + (meta.subject || '');
let dateOfBirth = parseDob(dobSource);

// If they replied with only the missing piece, the date they gave earlier may
// still be in the quoted thread. Accept it only when it is explicitly LABELLED
// as a date of birth: a loose date anywhere in quoted text is far more likely
// to be a mail client's timestamp than anyone's birthday.
if (!dateOfBirth) {
  const labelledDob = String(meta.bodyText || '')
    .match(/(?:date of birth|d\.?o\.?b\.?|born(?: on)?)\s*(?:is|:)?\s*([^\n,;.]{6,32})/i);
  if (labelledDob) dateOfBirth = parseDob(labelledDob[1]);
}

let ageYears = null;
if (dateOfBirth) {
  const dob = new Date(dateOfBirth + 'T00:00:00Z');
  const now = new Date();
  ageYears = now.getUTCFullYear() - dob.getUTCFullYear();
  const beforeBirthday = (now.getUTCMonth() < dob.getUTCMonth()) ||
    (now.getUTCMonth() === dob.getUTCMonth() && now.getUTCDate() < dob.getUTCDate());
  if (beforeBirthday) ageYears -= 1;
  if (ageYears < 0 || ageYears > 120) ageYears = null;
}

// ---- guardian email ------------------------------------------------------
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const allEmails = ownText.match(emailRe) || [];
const refCtx = $('Detect Reference Reply').item.json;
const notGuardian = [meta.fromEmail, refCtx.bankEmail, refCtx.opsTeamEmail]
  .map(e => String(e || '').toLowerCase());
const candidates = allEmails
  .map(e => e.toLowerCase())
  .filter(e => notGuardian.indexOf(e) === -1);

let guardianEmail = null;
const labelled = ownText.match(/(?:guardian|parent|father|mother|mum|mom|dad)[^\n]{0,40}?([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/i);
if (labelled) guardianEmail = labelled[1].toLowerCase();
if (!guardianEmail && candidates.length === 1) guardianEmail = candidates[0];
if (guardianEmail === meta.fromEmail) guardianEmail = null;

// ---- phone ---------------------------------------------------------------
let phoneNumber = null;
const phoneMatch = ownText.match(/(?:phone|mobile|cell|contact)[^\n]{0,20}?((?:\+?92|0)[\s-]?\d{3}[\s-]?\d{7})/i);
if (phoneMatch) phoneNumber = phoneMatch[1].replace(/\s+/g, ' ').trim();

// CONTINUATION: they answered a question we asked them.
//
// Live case, execution 418: we asked a new applicant for their date of birth,
// they replied with just "20/9/2000", and because that reply contains no
// intent words at all wantsOpen was false and they were told we did not
// recognise their address. Supplying a date of birth to a bank you are not
// registered with has exactly one meaning, so treat it as continuing the
// application -- but only on a REPLY, so a first-time stranger who happens to
// mention a date is not silently enrolled.
const repliedToUs = /\bOn\s+\w.{0,160}?\bwrote:/i.test(String(meta.bodyText || ''))
  || /-{2,}\s*Original Message/i.test(String(meta.bodyText || ''))
  || /^\s*>/m.test(String(meta.bodyText || ''))
  || /^\s*re\s*:/i.test(String(meta.subject || ''));
const suppliedDetailWeAskedFor = Boolean(dateOfBirth) || Boolean(guardianEmail);
const isContinuation = repliedToUs && suppliedDetailWeAskedFor
  && !result.wantsOpen && !result.wantsPolicy;

return [{ json: {
  wantsOpen: result.wantsOpen || isContinuation,
  wantsPolicy: result.wantsPolicy,
  wantsHelp: result.wantsHelp === true,
  isContinuation,
  fullName,
  accountType,
  dateOfBirth,
  ageYears,
  isMinor: ageYears !== null && ageYears < 18,
  guardianEmail,
  phoneNumber,
  fromEmail: meta.fromEmail,
  subject: meta.subject,
  bodyText: meta.bodyText
} }];

const item = $input.first().json;
const text = ((item.subject || '') + ' ' + (item.bodyText || '')).toLowerCase();

let accountType = 'checking';
if (/\bsavings?\b/.test(text)) accountType = 'savings';

// Mandate: either-or (any holder acts alone) is the default; all-signatures means
// every holder has to approve each transfer. Only switch on an explicit request.
let authorityModel = 'either_or';
if (/\b(both (of us |signatures?|holders?|must|have to|need)|all (signatures?|holders?)|two signatures?|dual (signature|control|authorisation|authorization)|joint(ly)? sign|require[sd]? (both|all))\b/.test(text)) {
  authorityModel = 'all_signatures';
}
if (/\b(either (of us|one)|any (one )?(of us|holder)|single signature|independently|on (my|our) own)\b/.test(text)) {
  authorityModel = 'either_or';
}

if (!item.jointInviteeEmail) {
  return [{ json: { ok: false, reason: 'We could not find an email address to invite. Please include it clearly, for example: "I want to open a joint account with bob@example.com".', fromEmail: item.fromEmail, subject: item.subject, full_name: item.full_name } }];
}

return [{ json: {
  ok: true,
  inviter_profile_id: item.profile_id,
  invitee_email: item.jointInviteeEmail,
  account_type: accountType,
  authority_model: authorityModel,
  authority_label: authorityModel === 'all_signatures'
    ? 'both holders must approve every transfer'
    : 'either holder can act on their own',
  fromEmail: item.fromEmail,
  subject: item.subject,
  full_name: item.full_name
} }];

const meta = $('Extract Email Metadata').item.json;
const rows = $input.all().filter(r => r.json && r.json.id);
const invite = rows.length > 0 ? rows[0].json : null;

const bodyLower = (meta.bodyText || '').toLowerCase().trim();

// Guard against false positives: an ordinary transfer/balance/policy/account-
// opening email must NEVER be misread as an invitation response just because
// it happens to contain a common word like "yes". A real invitation reply is
// short and single-purpose, so we require either explicit phrasing, or a
// short reply with no other strong banking intent present.
const looksLikeOtherIntent = /\b(transfer|send money|remit|wire|balance|how much|policy|policies|\bfees?\b|\blimits?\b|overdraft|open an account|open account|new account|standing order|recurring|dispute|fraud|unauthorized|unauthorised)\b/.test(bodyLower);

const explicitAccept = /\bi accept\b|\baccept(?:s|ed|ing)? the invitation\b|\baccept this invitation\b/.test(bodyLower);
const explicitDecline = /\bi decline\b|\bdecline the invitation\b|\bdecline this invitation\b|\bi reject\b/.test(bodyLower);

const wordCount = bodyLower.split(/\s+/).filter(Boolean).length;
const isShortReply = wordCount > 0 && wordCount <= 8;
const shortAccept = isShortReply && /\b(accept|agree|yes|confirm|ok|okay)\b/.test(bodyLower);
const shortDecline = isShortReply && /\b(decline|reject|no|refuse)\b/.test(bodyLower);

const wantsAccept = explicitAccept || (shortAccept && !looksLikeOtherIntent);
const wantsDecline = explicitDecline || (shortDecline && !looksLikeOtherIntent);

const isResponse = !!invite && (wantsAccept || wantsDecline) && !(wantsAccept && wantsDecline);

return [{
  json: {
    isResponse,
    invitation_id: invite ? invite.id : null,
    accept: wantsAccept && !wantsDecline,
    fromEmail: meta.fromEmail,
    subject: meta.subject,
    bodyText: meta.bodyText,
    rawFrom: meta.rawFrom,
    messageId: meta.messageId,
    threadId: meta.threadId
  }
}];

