parameters.jsCode:
const original = $('Classify Intent & Authorize Request').item.json;
const valid = ['JOINT_OPEN','OPEN_ACCOUNT','ACCOUNT_CLOSURE','STATEMENT','DISPUTE',
               'LOAN_APPLICATION','LOAN_CANCEL','DEPOSIT','STANDING_ORDER','TRANSFER',
               'BALANCE','POLICY_RAG','UNAUTHORIZED_ACCESS','UNKNOWN'];

let intent = String($json.output || $json.text || '').trim().toUpperCase().replace(/[^A-Z_]/g, '');
if (valid.indexOf(intent) === -1) intent = 'UNKNOWN';

// A security verdict is not a classification opinion. If the keyword pass found
// the sender naming an account they do not hold, that stands whatever the model
// thought the email was about.
if (original.intent === 'UNAUTHORIZED_ACCESS') intent = 'UNAUTHORIZED_ACCESS';

// Same for a transfer with nothing to act on: the model calling it a TRANSFER
// does not conjure an amount or a recipient out of the text.
if (intent === 'TRANSFER') {
  const td = original.transferDetails || {};
  if (!td.amount && !td.destination_account) intent = 'POLICY_RAG';
}

return [{ json: Object.assign({}, original, { intent }) }];

const original = $('Extract New Sender Intent').item.json;
const raw = String(($json.output || $json.text || '')).trim().toUpperCase().replace(/[^A-Z]/g, '');

const wantsOpen = raw === 'OPEN_ACCOUNT' || raw === 'OPENACCOUNT';
const wantsPolicy = raw === 'POLICY';

return [{
  json: {
    wantsOpen,
    wantsPolicy,
    fullName: original.fullName,
    accountType: original.accountType,
    fromEmail: original.fromEmail,
    subject: original.subject,
    bodyText: original.bodyText
  }
}];

// Every email the bank sends that needs a human answer carries a short reference
// code. When that human replies, the code comes back to us and tells us exactly
// which pending decision this is. Four families:
//   OPS-xxxxxxxx  a bank decision, only the ops mailbox may answer it
//   JNT-xxxxxxxx  a joint-account action, only a holder (or, for an invitation
//                 to join, the invited person) may answer it - checked in SQL
//   MIN-xxxxxxxx  a guardian consent, only the named guardian may answer it
//   DSP-xxxxxxxx  a dispute, co-holders adding their side of the story

// Who the operations team is, and which mailbox is theirs, is a database
// question now -- there can be more than one operator.
const staff = $('Check Sender Is Staff').item.json;
const OPS_TEAM_EMAIL = staff.ops_inbox;
const IS_STAFF = staff.is_staff === true;
const BANK_EMAIL = 'bank@yourbank.example';

const meta = $('Extract Email Metadata').item.json;
const from = String(meta.fromEmail || '').toLowerCase().trim();
const subject = String(meta.subject || '');
const body = String(meta.bodyText || '');

const passthrough = Object.assign({}, meta, {
  isRefReply: false, refKind: null, refCode: null,
  decision: null, opsNote: null,
  opsTeamEmail: OPS_TEAM_EMAIL, bankEmail: BANK_EMAIL, isStaff: IS_STAFF
});

const refMatch = (subject + '\n' + body).match(/\b(OPS|JNT|MIN|DSP)-([A-Za-z0-9]{8})\b/);
if (!refMatch) {
  return [{ json: passthrough }];
}

const prefix = refMatch[1].toUpperCase();
const refCode = prefix + '-' + refMatch[2].toUpperCase();
let refKind = prefix === 'OPS' ? 'ops'
            : prefix === 'JNT' ? 'joint'
            : prefix === 'MIN' ? 'minor'
            : 'dispute';

// An OPS code is only actionable when an operator sends it back. Anyone else
// quoting the code at us is just a normal customer email. Any operator may
// answer it, not only the mailbox it happened to be addressed to.
if (refKind === 'ops' && !IS_STAFF) {
  return [{ json: passthrough }];
}

// Gmail quotes the original message in a reply, so the decision must be read from
// what the person actually typed -- everything above the first quote marker.
let ownText = body;
const cutMarkers = [/-{2,}\s*Original Message/i, /\bOn\s+\w.{0,160}?\bwrote:/i, /^\s*>/m, /_{10,}/, /\bSent from (?:Proton Mail|my iPhone|my iPad|my Android|Yahoo Mail|Outlook)/i, /={3,}BANKING-OPS-ACTION/];
let cutAt = ownText.length;
for (const marker of cutMarkers) {
  const hit = ownText.match(marker);
  if (hit && hit.index !== undefined && hit.index >= 0 && hit.index < cutAt) cutAt = hit.index;
}
ownText = ownText.slice(0, cutAt);

// An explicit NOTE: line lets ops attach a rejection reason or an edited answer,
// and lets a co-holder attach their side of a dispute.
let opsNote = null;
const noteMatch = ownText.match(/^\s*NOTE\s*:\s*([\s\S]+)$/im);
if (noteMatch) {
  opsNote = noteMatch[1].trim() || null;
  ownText = ownText.slice(0, noteMatch.index);
}

// n8n substitutes the literal string "No Subject" when an email has none,
// and "No" matches the rejection pattern below. Every decision sent without
// a subject line therefore contained both an approval and a rejection, was
// treated as ambiguous, and left the request pending until it expired.
// A placeholder is not something the sender typed, so it does not get a vote.
const typedSubject = /^\s*(?:re:\s*)?\(?no subject\)?\s*$/i.test(subject) ? '' : subject;
const decisionText = (typedSubject + '\n' + ownText);
const saysApprove = /\b(approve|approved|approves|accept|accepted|authorise|authorised|authorize|authorized|yes|agreed?|confirm|confirmed)\b/i.test(decisionText);
const saysReject  = /\b(reject|rejected|rejects|decline|declined|deny|denied|refuse|refused|no|disagreed?)\b/i.test(decisionText);

let decision = null;
if (saysApprove && !saysReject) decision = 'approve';
else if (saysReject && !saysApprove) decision = 'reject';

// Both words, or neither: we must NOT guess. Passing "not approve" through as a
// rejection would silently kill a pending request because someone replied
// "no problem, thanks". Route to a clarification email instead and leave the
// request untouched and still pending.
if (decision === null) {
  refKind = 'unclear';
}

return [{ json: Object.assign({}, meta, {
  isRefReply: true, refKind, refCode, decision, opsNote,
  opsTeamEmail: OPS_TEAM_EMAIL, bankEmail: BANK_EMAIL, isStaff: IS_STAFF
}) }];

