// Both auth-user creations run with neverError, so an address that was already a
// customer simply comes back as an error we ignore. The authoritative mapping is
// this profiles lookup, which covers both the newly created and the pre-existing case.
const consent = $('Respond To Guardian Consent').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.email);

function idFor(email) {
  const hit = rows.find(r => String(r.email).toLowerCase() === String(email).toLowerCase());
  return hit ? hit.id : null;
}

const minorProfileId = idFor(consent.applicant_email);
const guardianProfileId = idFor(consent.guardian_email);

return [{ json: {
  ref_code: consent.ref_code,
  applicant_email: consent.applicant_email,
  applicant_name: consent.applicant_name,
  guardian_email: consent.guardian_email,
  minor_profile_id: minorProfileId,
  guardian_profile_id: guardianProfileId,
  profiles_resolved: Boolean(minorProfileId && guardianProfileId)
} }];

