parameters.jsCode:
// One place to turn every possible joint-action outcome into plain language, so
// the email nodes below stay simple. Four distinct outcomes:
//   declined by this holder / still waiting on others / executed / execution failed
const r = $input.first().json;
const reply = $('Detect Reference Reply').first().json;
const accepted = reply.decision === 'approve';

const amount = r.payload && r.payload.amount ? 'Rs ' + (Number(r.payload.amount) / 100).toFixed(2) : null;
const what = r.action_type === 'transfer_approval' ? ('a transfer of ' + (amount || 'funds'))
           : r.action_type === 'close_account' ? 'closing the account'
           : r.action_type === 'add_holder' ? 'adding a new account holder'
           : 'this request';

const pending = Array.isArray(r.pending_holder_emails) ? r.pending_holder_emails : [];

let headline, detail, notifyRequester = true;

if (!accepted || r.status === 'rejected') {
  headline = 'Request ' + r.ref_code + ' has been declined';
  detail = 'You declined ' + what + ' on account ' + (r.account_number || '') +
    '. Nothing has been changed and no money has moved. The request is now closed.';
} else if (r.success === false) {
  headline = 'Request ' + r.ref_code + ' could not be completed';
  detail = 'All required signatures were collected, but we could not carry out ' + what +
    '.\n\nReason: ' + (r.error || 'unknown error') +
    '\n\nNothing has been changed and no money has moved. The request stays open, so it can be ' +
    'retried once the cause is resolved.';
} else if (r.requires_additional_signatures) {
  headline = 'Your approval for ' + r.ref_code + ' is recorded';
  detail = 'Thank you. We still need ' + (r.required - r.consents_count) + ' more approval(s) before ' +
    what + ' on account ' + (r.account_number || '') + ' can go ahead.' +
    (pending.length ? '\n\nStill to approve: ' + pending.join(', ') : '');
  notifyRequester = false;
} else {
  headline = 'Request ' + r.ref_code + ' is complete';
  detail = 'All holders have approved, and ' + what + ' on account ' + (r.account_number || '') +
    ' has been carried out.' +
    (r.transaction_id ? '\n\nTransaction reference: ' + r.transaction_id : '');
}

return [{ json: {
  headline,
  detail,
  ref_code: r.ref_code,
  responderEmail: r.responder_email || reply.fromEmail,
  requesterEmail: r.requester_email || null,
  notifyRequester: notifyRequester && Boolean(r.requester_email) &&
                   String(r.requester_email).toLowerCase() !== String(r.responder_email || '').toLowerCase()
} }];

