parameters.jsCode:
// Late intent overrides, applied AFTER both classifier paths (keyword and LLM)
// have had their say, so these rules live in one place instead of being
// duplicated into two 4KB classifiers that must be kept identical.
//
// They only ever promote UNKNOWN. That is deliberate:
//   "what is your account closure policy"  -> POLICY_RAG, they want an answer, not a closure
//   "close my account and send the balance to ACC-123" -> TRANSFER, move the money first
// Overriding either of those would do the customer real harm, so a confident
// classification is never second-guessed here.
const item = $input.first().json;
const intent = String(item.intent || '');

if (intent !== 'UNKNOWN') {
  return [{ json: item }];
}

const text = ((item.subject || '') + ' ' + (item.bodyText || '')).toLowerCase();

// --- statements ------------------------------------------------------------
// Checked before closure: "send me a statement for the account I closed" is a
// statement request, not a closure request.
const wantsStatement = /\b(statement|statements|transaction history|account history|list of transactions|activity report)\b/.test(text);
if (wantsStatement) {
  return [{ json: Object.assign({}, item, { intent: 'STATEMENT' }) }];
}

// --- closure ---------------------------------------------------------------
const closureVerb = /\b(close|closing|closure|delete|deleting|deactivate|terminate|terminating|cancel|cancelling|canceling|shut\s?down)\b/.test(text);
const mentionsAccount = /\b(account|acc|acct)\b/.test(text);
// "cancel my standing order on that account" is a standing-order request, not a
// closure request, and the two share the verb 'cancel'.
const isStandingOrder = /\b(standing order|recurring|scheduled payment|direct debit|subscription)\b/.test(text);

if (closureVerb && mentionsAccount && !isStandingOrder) {
  return [{ json: Object.assign({}, item, { intent: 'ACCOUNT_CLOSURE' }) }];
}

return [{ json: item }];

// Input is Route by Intent, which carries whichever classification won (keyword
// or LLM), so read $input rather than naming a specific classifier node.
const ctx = $input.first().json;
const haystack = ((ctx.bodyText || '') + ' ' + (ctx.subject || '')).toUpperCase();
const all = ctx.authorizedAccounts || [];
const active = all.filter(a => a.status === 'active');

function out(extra) {
  return [{ json: Object.assign({
    fromEmail: ctx.fromEmail,
    subject: ctx.subject,
    full_name: ctx.full_name,
    profile_id: ctx.profile_id
  }, extra) }];
}

if (active.length === 0) {
  const closedCount = all.length - active.length;
  return out({ ok: false, reason: closedCount > 0
    ? 'We could not find an open account in your name. It looks like your account(s) with us are already closed.'
    : 'We could not find an open account in your name to close.' });
}

// A minor holder cannot close the account any more than they can empty it.
const minorOnly = active.every(a => a.holder_type === 'minor');
if (minorOnly) {
  return out({ ok: false, reason: 'This is a guardian-supervised account. Your parent or guardian needs to ask us to close it, from their own email address.' });
}

const mentioned = haystack.match(/\b(TEST|ACC|JNT)-[A-Z0-9-]+\b/g) || [];
let target = null;
for (const m of mentioned) {
  const hit = active.find(a => String(a.account_number).toUpperCase() === m);
  if (hit) { target = hit; break; }
}

if (!target) {
  if (active.length === 1) {
    target = active[0];
  } else {
    // Never guess which account to close when the customer holds several.
    const list = active.map(a => '  ' + a.account_number + ' - ' + a.account_type +
      ', balance Rs ' + (Number(a.balance) / 100).toFixed(2)).join('\n');
    return out({ ok: false, needsAccountChoice: true, accountList: list,
      reason: 'You hold more than one open account with us, so we need you to tell us which one to close.' });
  }
}

if (target.holder_type === 'minor') {
  return out({ ok: false, reason: 'That account is guardian-supervised. Your parent or guardian needs to ask us to close it, from their own email address.' });
}

return out({
  ok: true,
  account_id: target.account_id,
  account_number: target.account_number,
  account_type: target.account_type,
  balance: target.balance
});

