} }));

// Input is Route by Intent, which carries whichever classification won.
const ctx = $input.first().json;
const text = ((ctx.bodyText || '') + ' ' + (ctx.subject || ''));
const hay = text.toUpperCase();
const lower = text.toLowerCase();
const active = (ctx.authorizedAccounts || []).filter(a => a.status === 'active');

function out(extra) {
  return [{ json: Object.assign({
    fromEmail: ctx.fromEmail, subject: ctx.subject,
    full_name: ctx.full_name, profile_id: ctx.profile_id
  }, extra) }];
}

if (active.length === 0) {
  return out({ ok: false, reason: 'We could not find an open account in your name to produce a statement for.' });
}

let target = null;
const mentioned = hay.match(/\b(TEST|ACC|JNT)-[A-Z0-9-]+\b/g) || [];
for (const m of mentioned) {
  const hit = active.find(a => String(a.account_number).toUpperCase() === m);
  if (hit) { target = hit; break; }
}
if (!target) {
  if (active.length === 1) {
    target = active[0];
  } else {
    const list = active.map(a => '  ' + a.account_number + ' - ' + a.account_type).join('\n');
    return out({ ok: false, needsAccountChoice: true, accountList: list,
      reason: 'You hold more than one open account, so we need to know which one the statement is for.' });
  }
}

// Period. Default is the last full calendar month, which is what "my statement"
// almost always means. "This month" is honoured explicitly because a
// month-to-date statement is a reasonable and different thing to ask for.
function iso(d) { return d.toISOString().slice(0, 10); }
const now = new Date();
let from, to, label;

const explicit = text.match(/\b((?:19|20)\d{2}-\d{2}-\d{2})\b[^\d]{1,12}\b((?:19|20)\d{2}-\d{2}-\d{2})\b/);
if (explicit) {
  from = explicit[1]; to = explicit[2]; label = from + ' to ' + to;
} else if (/\b(this month|current month|month to date|so far this month)\b/.test(lower)) {
  from = iso(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)));
  to = iso(now);
  label = 'this month so far';
} else if (/\b(this year|year to date)\b/.test(lower)) {
  from = iso(new Date(Date.UTC(now.getUTCFullYear(), 0, 1)));
  to = iso(now);
  label = 'this year so far';
} else {
  const firstOfThis = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  const lastOfPrev = new Date(firstOfThis.getTime() - 86400000);
  from = iso(new Date(Date.UTC(lastOfPrev.getUTCFullYear(), lastOfPrev.getUTCMonth(), 1)));
  to = iso(lastOfPrev);
  label = 'last month';
}

return out({ ok: true, account_id: target.account_id,
  account_number: target.account_number, period_start: from, period_end: to,
  period_label: label });

