parameters.jsCode:
// An address asking to join the operations team. Deliberately requires an
// explicit PASSPHRASE: line rather than trying every unrecognised email
// against the phrase -- that would burn an innocent sender's attempt budget
// and turn every stray message into a guess.
//
// Only what the sender typed counts. If the quoted part of a reply were read
// too, forwarding an enrolment email to someone would hand them the phrase and
// let them enrol by replying to it.
const meta = $json;

function ownTextOf(body) {
  const t = String(body || '');
  const markers = [
    /-{2,}\s*Original Message/i,
    /\bOn\s+\w.{0,160}?\bwrote:/i,
    /^\s*>/m,
    /_{10,}/,
    /\bSent from (?:Proton Mail|my iPhone|my iPad|my Android|Yahoo Mail|Outlook)/i,
    /\bFrom:\s*.{0,120}\bSent:/i
  ];
  let cut = t.length;
  for (const m of markers) {
    const hit = t.match(m);
    if (hit && hit.index !== undefined && hit.index >= 0 && hit.index < cut) cut = hit.index;
  }
  return t.slice(0, cut);
}

const own = ownTextOf(meta.bodyText);
const m = own.match(/^[ \t]*PASS[ \t]?PHRASE[ \t]*:[ \t]*(.+)$/im);
const phrase = m ? m[1].trim() : null;

return [{ json: Object.assign({}, meta, {
  isEnrolment: !!phrase,
  enrolmentPhrase: phrase
}) }];

