parameters.jsCode:
// The recipient is told money arrived. Until now only the sender heard
// anything, which is the half that already knew.
//
// Every holder of the destination account is told, because on a joint account
// they are all equally the recipient. The sender is skipped -- moving money
// between two accounts you hold should not email you twice.
const t = $('Resolve Transfer Target & Authorize').item.json;
const dest = $('Look Up Destination Account').item.json;
const sender = String(t.fromEmail || '').toLowerCase();

const holders = (dest.holder_emails || [])
  .filter(e => String(e).toLowerCase() !== sender);

return holders.map(e => ({ json: {
  recipientEmail: e,
  amount: t.amount,
  destinationAccount: dest.account_number,
  senderAccount: t.source_account_number,
  senderName: t.full_name
} }));

