parameters.jsCode:
const res = $json;
const rows = res.approvals || [];

if (!res.success) {
  return [{ json: { body: res.error || 'Could not read the approval queue.' } }];
}

if (rows.length === 0) {
  return [{ json: { body: 'Nothing is waiting for a decision.' } }];
}

const lines = rows.map(r => {
  const mine = r.yours_to_decide
    ? 'reply APPROVE ' + r.ref_code + '  or  REJECT ' + r.ref_code
    : 'the administrator decides this one';
  return [
    r.ref_code + '  (' + r.request_type + ')',
    '  ' + r.subject,
    '  raised ' + r.created_at + ', expires ' + r.expires_at +
      ' -- ' + r.days_left + ' day(s) left',
    '  ' + mine
  ].join('
');
});

return [{ json: { body:
  rows.length + ' request(s) waiting for a decision:

' + lines.join('

') +
  '

You can answer any of these in a NEW email -- it does not have to be a ' +
  'reply. Put the reference code and the single word APPROVE or REJECT in the ' +
  'message, and add a NOTE: line if you want to record why.'
} }];

